    {
      "label": "QUOTE",
      "frame": "མདོ་དགོངས་པ་འདུས་པ་ལས།",
      "head": "སེམས་ཀྱི་དཀྱིལ་འཁོར་རང་བཞིན་གྱིས་འོད་གསལ་བ་གསང་སྡགས་ཀྱི་དེ་ཁོ་ན་ཉིད།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྒྱུད་ཀྱི་རྒྱལ་པོ་རྡོ་རྗེ་སེམས་དཔའ་སྒྱུ་འཕྲུལ་དྲ་བ་ལས།",
      "head": "སངས་རྒྱས་ཉིད་ལས་གཞན་པའི་ཆོས། །སངས་རྒྱས་ཉིད་ཀྱིས་མི་བརྙེས་སོ༑ ༑",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "སྤྲོས་བྲལ་དོན་གསལ་ཆེན་པོའི་རྒྱུད་ལས།",
      "head": "རིག་པ་དངོས་མེད་ཡེ་དག་ཟང་ཐལ་ཆེན་པོ་དེ་ལས། ",
      "tail": "འདས་ཐམས་ཅད་སྣང་བའི་ཕྱིར་གཞི་གནས་ཀྱི་ཡེ་ཤེས་སོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "སྤྲོས་བྲལ་དོན་གསལ་ཆེན་པོའི་རྒྱུད་ལས།",
      "head": "ངོ་བོ་ཉིད་ནི་མ་བྱས་པ་མ་བཅོས་པ། །མ་བསླད་པ། མི་འགྱུར་བ། རང་བཞིན་རྣམ་པར་དག་པ། འདུས་མ་བྱས་པ། གསལ་བའི་ཡེ་ཤེས་ཆེན་པོ་ནམ་མཁའ་ལྟ་བུའི་ཆོས་ཉིད། སྟོང་པ་རྡོ་རྗེའི་ཆོས་ཅན། རིག་པ་དངོས་མེད་ཡེ་དག་ཟང་ཐལ་ཆེན་པོའོ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "སྤྲོས་བྲལ་དོན་གསལ་ཆེན་པོའི་རྒྱུད་ལས།",
      "head": "རིག་པ་གསལ་སྟོང་གཉུག་མེད་ཟང་ཐལ་ཡིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ངས་བསྟན་རྒྱུད་ལུང་ཐམས་ཅད་དུ། །",
      "head": "འགྱུར་བ་མེད་དང་འདུས་མ་བྱས། །རྡོ་རྗེ་ལྟ་བུའི་ཚིག་བརྗོད་ན། །རང་བྱུང་ཡེ་ཤེས་ཆེན་པོར་བཤད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "གཞི་འགྱུར་བ་མེད་པ་ཡེ་ནས་སངས་རྒྱས་པ་བཅོམ་ལྡན་འདས་རྡོ་རྗེ་འཆང་ཆེན་པོ་ཡིན་པས།",
      "head": "སྡར་ཡང་འཁྲུལ་མ་མྱོང་། ད་ལྟ་ཡང་མ་འཁྲུལ། ཕྱིས་ཀྱང་འཁྲུལ་མི་སྲིད་དོ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཡང་དག་དོན་གྱི་གཞི་མོ་ནི།",
      "head": "རིག་པ་ཙམ་དུ་མཐུན་པའི་ཚོགས་བརྒྱད་ལས་གྲོལ་ཏེ། འཕེལ་འགྲིབ་མེད་པས་ཀུན་གཞིའི་རྣམ་ཤེས་ལས་གྲོལ། གཟུང་འཛིན་མེད་པས་ཡིད་ཀྱི་རྣམ་ཤེས་ལས་གྲོལ། སྐྱེ་འགག་མེད་པས་སྒོ་ལྔའི་རྣམ་ཤེས་ལས་གྲོལ་ཞིང་ལོག་པའོ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "གཞི་དེ་ལ་རང་བཞིན་ལྷུན་གྱིས་གྲུབ་པའི་སངས་རྒྱས་དང་། གཞོན་ནུ་བུམ་པའི་སྐུ་དང་། ཆོས་སྐུ་དང་། ངོ་བོ་ཉིད་སྐུ་དང་། ངོ་བོ་རང་བཞིན་ཐུགས་རྗེ་གསུམ་དུ་བརྗོད་ཚུལ་རྒྱ་ཆེར་གསུངས་པ་དང་། རིགས་ཀྱི་བུ།",
      "head": "ངོ་བོ་ཆོས་ཀྱི་སྐུ། རང་བཞིན་ལོངས་སྐུ། ཐུགས་རྗེ་སྤྲུལ་སྐུ་སྟེ་ཐམས་ཅད་ཀྱི་གཞིར་མ་འགག་པར་གནས་པས་གཞི་གནས་ཀྱི་སྐུ་གསུམ་མོ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "མཚན་ཉིད་དེ་སྡེ་གསུམ་ལས་ཇ་ལོག་སྟེ།",
      "head": "འདུས་བྱས་ཀྱི་ཆོས་ཀ་ནས་དག་པས་རང་བྱུང་གི་ཡེ་ཤེས་ལྷུན་གྱིས་གྲུབ་པའོ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ལྟ་བའི་གོལ་ས་བཅད་པ་བསྟན་པ་ནི། །",
      "head": "རང་བྱུང་ཡིན་པས་རྒྱུ་རྐྱེན་གོལ་ས་ཆོད། །སྟོང་པར་འདུག་པས་དངོས་པོའི་གོལ་ས་ཆོད། །གསལ་བར་འདུག་པས་སྟོང་པའི་གོལ་ས་ཆོད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཡིད་ཀྱི་རྣམ་ཤེས་མཚན་ཉིད་བསྟན་པ་ནི། །",
      "head": "ཕྱི་རུ་ཡུལ་ལྔ་སྤྱོད་པའི་བདག་པོ་བྱེད། །ནང་དུ་དེ་ལ་བཟུང་བའི་ཉོན་མོངས་ཡིད། །གཟུང་དང་འཛིན་པ་གཉིས་ཀྱི་བདག་པོ་ཡིན། །དེ་ཡི་ཕྱིར་ན་རྣམ་པར་རྟོག་པ་རྣམས། །རང་གི་རིག་པ་དག་གི་རྩལ་ཡིན་ཏེ། །འཛིན་མེད་གསལ་བའི་རིག་པ་དེ་ཉིད་ནི། །རིག་པར་འགྱུས་ཀྱང་འཛིན་པའི་རྫོགས་མེད་དེ། །ཕྱི་རུ་ཡུལ་ལ་སྤྱད་ཀྱང་མ་བཟུང་ན། །ལྟ་བ་ཟང་ཐལ་ཡིན་ཏེ་ཡིད་ལས་ལྡོག །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྫོགས་ཆེན་ངེས་དོན་འདུས་པའི་རྒྱུད་ལས།",
      "head": "རྗེས་ལ་བཙལ་བས་གླང་པོ་རྙེད། །སེམས་ཀྱི་ཕྱོགས་ནས་དོན་བཙལ་ན། །རང་རིག་ཡེ་ཤེས་རྒྱལ་པོ་རྙེད། །དེ་རྙེད་སེམས་སུ་འཛིན་པ་བྲལ། །འཛིན་བྲལ་སེམས་མེད་རང་བྱུང་སྐུ། །སེམས་ལས་མ་བྱུང་སངས་རྒྱས་རྙེད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཀུན་ཏུ་བཟང་པོ་ཡེ་ཤེས་ཀློང་གི་རྒྱུད་རིན་ཆེན་གསེར་གྱི་ཡང་ཞུན་ལས།",
      "head": "རིག་པ་མ་བསླད་ཆོས་སྐུ་ཡི། །རང་བཞིན་ངོ་བོ་ཉིད་ཀྱི་སྐུ། །རྒྱུ་རྐྱེན་མ་སྐྱེས་འགྱུར་བ་མེད། །འདུས་མ་བྱས་འདི་ནམ་མཁའ་འདྲ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྫོགས་པ་ཆེན་པོ་ནམ་མཁའ་དང་མཉམ་པའི་རྒྱུད་ལས།",
      "head": "པདྨ་འདམ་གྱིས་མ་གོས་ལྟར། །བྱང་ཆུབ་སེམས་ཀྱི་ངོ་བོ་ལ། །གཟུང་འཛིན་དྲི་མ་གཞི་ལ་མེད། །དེ་ཕྱིར་རང་བྱུང་སྙིང་པོ་འདི། །སུས་ཀྱང་མ་བྱས་མཛད་བཅོས་མིན། །རང་བྱུང་རིག་པའི་རྒྱལ་པོ་ཡིན། །དེ་ཕྱིར་འདུས་མ་བྱས་པའི་ཐུགས། །དེ་ལ་གཉེན་པོས་མི་ཤིག་ཕྱིར། །བཞག་ཅིང་བླང་པར་ནུས་པ་མེད། །དེ་དོན་རྟོགས་པའི་རྣལ་འབྱོར་དེས། །མི་ཡི་ལུས་ལ་སངས་རྒྱས་ཐུགས། །རང་བྱུང་སྐུ་ལ་ཚངས་པའི་གསུངས། །དེ་མ་ཐག་ཏུ་ཀུན་བཟང་ཉིད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྫོགས་པ་ཆེན་པོ་ནམ་མཁའ་དང་མཉམ་པའི་རྒྱུད་ལས།",
      "head": "དུས་གསུམ་སངས་རྒྱས་སེམས་དང་བྲལ། །ཚོགས་བརྒྱད་མེད་པས་སེམས་ཀྱང་མེད། །རང་བྱུང་སྙིང་པོ་ཆོས་ཀྱི་སྐུ། །སེམས་ལས་མ་བྱུང་ཡེ་ཤེས་མིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྫོགས་ཆེན་ལྟ་བ་ཡེ་ཤེས་གཏིང་རྫོགས་ཀྱི་རྒྱུད་ལས།",
      "head": "ཡེ་ནས་གནས་པའི་རང་བྱུང་སྙིང་པོ་འདི། །རྒྱུ་ལས་མ་བྱུང་རྐྱེན་གྱིས་མ་བསྐྱེད་པས། །རྩོལ་བ་གང་ཡང་མ་བྱས་ཆོས་སྐུ་རུ། །རང་བྱུང་ཡེ་ཤེས་ཡིན་པར་ཡིད་ཀྱང་ཆེས། །",
      "tail": ""
    },
    {
